const inItems = $input.all().map(i => i.json);
// вход либо из кэша (один item с __rows), либо строками листа
const rows = (inItems.length === 1 && Array.isArray(inItems[0].__rows)) ? inItems[0].__rows : inItems;
const u = $('Выделяю переменные пользователя').first().json;
const norm = p => String(p || '').replace(/\D/g, '').replace(/^8/, '7');
const st = $getWorkflowStaticData('global');

// Ключ агента = Telegram user_id. Своего номера у представителей не существует,
// прежний AgentNumber был выдуманным (и читался из колонки, которой в листе нет).
// Идентификация для аналитика — route_code: 1 маршрут = 1 агент.
const pick = (r, keys) => {
  for (const k of keys) {
    const v = r[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const pack = (r, action, extra) => [{ json: {
  ...u,
  action,
  stores: r.Stores || '',
  agent_id: String(u.user_id),
  route_code: pick(r, ['route_code', 'RouteCode', 'Route Code', 'Маршрут']),
  ...(extra || {}),
} }];

// 1) уже привязан по TelegramId
const byId = rows.find(r => String(r.TelegramId || '') === String(u.user_id));
if (byId) return pack(byId, 'proceed');

// 2) пришёл собственный контакт → ищем по телефону
if (u.is_contact && String(u.contact_user_id) === String(u.user_id)) {
  const byPhone = rows.find(r => norm(r.UserPhone) === norm(u.contact_phone));
  if (byPhone) {
    st.adminsAt = 0;  // сразу после регистрации кэш протух: TelegramId допишется в лист
    return pack(byPhone, 'registered', { match_phone: byPhone.UserPhone });
  }
  return [{ json: { ...u, action: 'reject' } }];
}

// 3) не привязан и это не контакт
return [{ json: { ...u, action: 'ask_contact' } }];

const u = $input.first().json;
const msg = u.message || u.edited_message || {};
const from = msg.from || (u.callback_query && u.callback_query.from) || {};
const contact = msg.contact || null;
const msgText = msg ? msg.text : '';
const photo = msg.photo || '';
const doc = msg.document || null;   // №10: «отправить файлом» — фото без пережатия Telegram

// ── Документ-как-фото ─────────────────────────────────────────
// Принимаем только то, что реально ест Gemini: JPEG / PNG / WEBP / HEIC / HEIF.
// mime приходит от клиента и врать может, поэтому достаточно совпадения ЛИБО mime,
// ЛИБО расширения имени файла; окончательный mime всё равно определит WF-2 по байтам.
const IMG_MIME = /^image\/(jpe?g|png|webp|heic|heif)$/i;
const IMG_EXT  = /\.(jpe?g|png|webp|heic|heif)$/i;
const TG_MAX   = 20 * 1024 * 1024;   // потолок getFile облачного Bot API: больше бот не скачает

const docIsImage = !!doc && (IMG_MIME.test(String(doc.mime_type || '')) || IMG_EXT.test(String(doc.file_name || '')));
const docTooBig  = !!doc && Number(doc.file_size || 0) > TG_MAX;

let kind, badReason = null;
if (u.callback_query)                      kind = 'callback';
else if (photo.length)                     kind = 'photo';
else if (doc && docIsImage && !docTooBig)  kind = 'photo';                 // ← документ идёт как фото
else if (doc)                            { kind = 'other'; badReason = !docIsImage ? 'not_image' : 'too_big'; }
else if (contact)                          kind = 'contact';
else if (msg.text)                         kind = 'text';
else                                       kind = 'other';

return [{ json: {
  user_id: from.id,
  chat_id: (msg.chat && msg.chat.id) || (u.callback_query && u.callback_query.message.chat.id),
  is_contact: !!contact,
  contact_phone:  contact ? contact.phone_number : null,
  contact_user_id: contact ? contact.user_id : null,
  update_kind: kind,
  text: msgText,
  photoFileId: photo.length ? photo[photo.length - 1].file_id : (kind === 'photo' && doc ? doc.file_id : null),

  // диагностика — видно в execution data, дальше по пайплайну не требуется
  input_kind: photo.length ? 'photo' : (doc ? 'document' : null),
  doc_name:   doc ? (doc.file_name || null) : null,
  doc_mime:   doc ? (doc.mime_type || null) : null,
  doc_size:   doc ? (Number(doc.file_size) || null) : null,
  bad_reason: badReason,
}}];

const TTL_MIN = 15;
const s = $input.first().json || {};
const upd = s.updated_at || '';
const code = String(s.current_store_code || '').trim();
const name = String(s.current_store_name || '').trim();

const ts = upd ? new Date(upd).getTime() : 0;
const alive = !!ts && (Date.now() - ts) < TTL_MIN * 60 * 1000;
const ready = !!(code && alive);

return [{ json: {
  store_ready: ready,
  current_store_code: ready ? code : null,
  current_store: ready ? name : null,
} }];

const PER_PAGE = 8;

// Показываем день недели полностью; фильтр по r.days по-прежнему идёт по сокращению.
const DAY_FULL = { 'Пн': 'Понедельник', 'Вт': 'Вторник', 'Ср': 'Среда', 'Чт': 'Четверг',
                   'Пт': 'Пятница', 'Сб': 'Суббота', 'Вс': 'Воскресенье' };
const dayName = d => DAY_FULL[String(d || '').trim()] || d;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function dayList(rows, mode, day) {
  if (mode === 'a') return rows;
  return rows.filter(r => String(r.days || '').split(',').map(s => s.trim()).includes(day));
}

function label(r) {
  const n = String(r.store_name || '').trim();
  const a = String(r.address || '').trim();
  const name = n.length > 30 ? n.slice(0, 29) + '…' : n;
  const addr = a.length > 32 ? a.slice(0, 31) + '…' : a;
  return addr ? name + ' — ' + addr : name;
}

function keyboard(list, page, route, mode) {
  const total = Math.max(1, Math.ceil(list.length / PER_PAGE));
  const cur = Math.min(Math.max(1, page), total);
  const kb = list.slice((cur - 1) * PER_PAGE, cur * PER_PAGE)
    .map(r => [{ text: label(r), callback_data: 'store:' + r.store_code }]);
  const nav = [];
  if (total > 1) {
    if (cur > 1) nav.push({ text: '◀️', callback_data: 'page:' + (cur - 1) + '|' + route + '|' + mode });
    nav.push({ text: cur + ' / ' + total, callback_data: 'noop' });
    if (cur < total) nav.push({ text: '▶️', callback_data: 'page:' + (cur + 1) + '|' + route + '|' + mode });
  }
  if (mode === 'd') nav.push({ text: '📋 Все точки', callback_data: 'all|' + route });
  if (mode === 'a') nav.push({ text: '📅 Только сегодня', callback_data: 'page:1|' + route + '|d' });
  if (nav.length) kb.push(nav);
  return kb;
}

const p = $('Точки: параметры').first().json;
const all = $input.all().map(i => i.json).filter(r => r && r.store_code);
const rows = dayList(all, p.mode, p.day);
const chat_id = $('Выделяю переменные пользователя').first().json.chat_id;

if (!p.route_code) {
  return [{ json: { chat_id, text: '⚠️ Вам не назначен маршрут. Сообщите администратору и заново отправьте фотографию.',
                    reply_markup: { inline_keyboard: [] } } }];
}
if (!all.length) {
  return [{ json: { chat_id, text: '⚠️ Маршрут ' + esc(p.route_code) + ' пуст или не загружен. Сообщите администратору.',
                    reply_markup: { inline_keyboard: [] } } }];
}
if (!rows.length) {
  return [{ json: { chat_id,
    text: 'На сегодня (<b>' + dayName(p.day) + '</b>) точек в маршруте нет.',
    reply_markup: { inline_keyboard: [[{ text: '📋 Показать все мои точки', callback_data: 'all|' + p.route_code }]] } } }];
}

return [{ json: {
  chat_id,
  text: 'Выберите магазин — ' + (p.mode === 'a' ? 'все точки маршрута' : '<b>' + dayName(p.day) + '</b>') + ', точек: ' + rows.length,
  reply_markup: { inline_keyboard: keyboard(rows, p.page, p.route_code, p.mode) },
} }];

const user = $input.first().json;
const chat_id = user.chat_id || user.user_id;
const action = 'ask_contact';
const isStart = ($('Проверка совпадения с базой').first().json.text || '').trim() === '/start';
const text = isStart
  ? 'Здравствуйте! Это ассистент для отчётов по растановке товаров на полке. Чтобы начать — нажмите на кнопку "Поделиться номером", мы проверим доступ.'
  : 'Сначала нужно авторизоваться. Поделитесь номером телефона:';
const reply_markup = { keyboard: [[{ text: '📱 Поделиться номером', request_contact: true }]], resize_keyboard: true, one_time_keyboard: true };
const telegram = { chat_id, text, reply_markup };

return [{ json: {
  action,
  chat_id,
  telegram
}}];

