const p = $('Страница: параметры').first().json;
const all = $input.all().map(i => i.json).filter(r => r && r.store_code);
const rows = dayList(all, p.mode, p.day);

let kb, answer = p.answer_text || '';
if (!rows.length) {
  kb = p.mode === 'd'
    ? [[{ text: '📋 Показать все мои точки', callback_data: 'all|' + p.route_code }]]
    : [];
  answer = answer || 'На сегодня точек нет';
} else {
  kb = keyboard(rows, p.page, p.route_code, p.mode);
}

return [{ json: {
  chat_id: p.chat_id,
  message_id: p.message_id,
  reply_markup: { inline_keyboard: kb },
  answer_text: answer,
} }];

