const u = $('Входящее сообщение').first().json;
const vars = $('Выделяю переменные пользователя').first().json;
const a = $('Проверка совпадения с базой').first().json;
const sess = $('Проверка сессии магазина').first().json;

let rows = [];
try { rows = $('Моя пачка').first().json.rows || []; } catch (e) { rows = []; }  // одиночное фото

const files = rows.length
  ? rows.map(r => ({ file_id: String(r.file_id), message_id: Number(r.message_id) || 0, row_key: String(r.row_key) }))
  : [{ file_id: vars.photoFileId,
       message_id: u.message.message_id,
       row_key: String(vars.chat_id) + '_' + String(u.message.message_id) }];

return files.map(f => ({ json: {
  file_id:    f.file_id,
  chat_id:    vars.chat_id,
  agent_id:   a.agent_id,
  route_code: a.route_code,
  store_name: sess.current_store,
  store_code: sess.current_store_code,
  message_id: f.message_id,
  row_key:    f.row_key,
  source:     'direct',
} }));

const u = $('Входящее сообщение').first().json;
const vars = $('Выделяю переменные пользователя').first().json;

let rows = [];
try { rows = $('Моя пачка').first().json.rows || []; } catch (e) { rows = []; }

const keys = rows.length
  ? rows.map(r => String(r.row_key))
  : [String(vars.chat_id) + '_' + String(u.message.message_id)];

return keys.map(row_key => ({ json: { row_key } }));

const all = $input.all().map(i => i.json);
const ok  = all.filter(r => r.status === 'ok');
const err = all.filter(r => r.status !== 'ok');
const items = ok.reduce((s, r) => s + (Number(r.items_count) || 0), 0);
const rowKey = r => String(r.chat_id) + '_' + String(r.message_id);

// очередь, отданная в WF-2 — источник правды по row_key (ошибочные прогоны его не возвращают)
let queued = [];
try { queued = $('Сбор очереди').all().map(i => i.json); } catch (e) {}
if (!queued.length) { try { queued = $('Сбор очереди (pending)').all().map(i => i.json); } catch (e) {} }
const ok_keys = ok.map(rowKey).filter(k => k.indexOf('undefined') === -1);
const all_keys = queued.map(q => String(q.row_key)).filter(Boolean);
const err_keys = all_keys.filter(k => ok_keys.indexOf(k) === -1);

const first = ok[0] || err[0] || {};
const chat_id = first.chat_id || $('Выделяю переменные пользователя').first().json.chat_id;
const store = first.store_name || '—';

// сжатая выкладка по одному фото: строки таблицы, сгруппированные по полке
function readout(r, num, many) {
  const rows = (r.items_brief || []).filter(it => it && it.name);
  if (!rows.length) return (many ? 'Фото ' + num + ': ' : '') + 'наших брендов не найдено';
  const byShelf = {};
  let total = 0;
  for (const it of rows) {
    const shelf = (it.shelf === 0 || it.shelf) ? String(it.shelf) : '—';
    const label = it.subtype ? (it.name + ' ' + it.subtype) : it.name;
    const cnt = Number(it.count) || 0;
    total += cnt;
    (byShelf[shelf] = byShelf[shelf] || []).push(label + ' ×' + cnt);
  }
  const head = (many ? '📸 Фото ' + num + ' — ' : '') + total + ' бут., ' + rows.length + ' поз.'
    + (r.low_confidence ? ' ⚠️' : '');
  const shelfLines = Object.keys(byShelf)
    .sort((a, b) => (parseInt(a) || 0) - (parseInt(b) || 0))
    .map(s => '  Полка ' + s + ': ' + byShelf[s].join(', '));
  return [head, ...shelfLines].join('\n');
}

const many = ok.length > 1;
const blocks = ok.map((r, i) => readout(r, i + 1, many));

let text = 'Готово ✅\nМагазин: ' + store
  + '\nФото обработано: ' + ok.length + ' из ' + all.length
  + '\nПозиций распознано: ' + items;
if (blocks.length) text += '\n\n' + blocks.join('\n\n');
if (err.length) text += '\n\n❌ Не обработалось: ' + err.length + '. Отправьте эти фото ещё раз.';
text += '\n\nСверьте счёт с полкой: всё верно — присылайте следующее фото; неточно — переснимите ближе и без бликов, затем пришлите заново.';

return [{ json: {
  chat_id, text,
  ok_keys, err_keys,
  ok_reports: ok.map(r => ({ key: rowKey(r), report_id: r.report_id || '' })),
} }];

const s = $input.first().json;
const iso = new Date().toISOString();
const rep = {};
(s.ok_reports || []).forEach(x => { rep[x.key] = x.report_id || ''; });

return [
  ...(s.ok_keys  || []).map(k => ({ json: { row_key: k, status: 'done',  processed_at: iso, report_id: rep[k] || '' } })),
  ...(s.err_keys || []).map(k => ({ json: { row_key: k, status: 'error', processed_at: iso, report_id: '' } })),
];

const rows = $input.first().json.rows || [];
const store = $('Обработка выбора магазина').first().json;
const cb = $('Входящее сообщение').first().json.callback_query;
const a = $('Проверка совпадения с базой').first().json;

return rows.map(r => ({ json: {
  file_id:    String(r.file_id),
  chat_id:    cb.message.chat.id,
  agent_id:   a.agent_id,
  route_code: a.route_code,
  store_name: store.store_name,
  store_code: store.store_code,
  message_id: Number(r.message_id) || 0,
  row_key:    String(r.row_key),
  source:     'pending',
} }));

const r = $input.first().json || {};
const found = !!(r && r.store_code);
return [{ json: {
  found,
  store_code: found ? String(r.store_code) : null,
  store_name: found ? String(r.store_name || '') : null,
  address:    found ? String(r.address || '') : null,
} }];

function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function readout(r) {
  const rows = (r.items_brief || []).filter(it => it && it.name);
  if (!rows.length) return 'Наших брендов на фото не найдено.';
  const NL = String.fromCharCode(10);
  const byShelf = {};
  for (const it of rows) {
    const shelf = (it.shelf === 0 || it.shelf) ? String(it.shelf) : '—';
    const name  = it.subtype ? it.subtype : it.name;
    const fmt   = it.format ? String(it.format) : 'объём ?';
    const cnt   = Number(it.count) || 0;
    (byShelf[shelf] = byShelf[shelf] || []).push(esc(name) + ' · ' + esc(fmt) + ' ×' + cnt);
  }
  const blocks = Object.keys(byShelf).sort((a,b)=>(parseInt(a)||0)-(parseInt(b)||0))
    .map(s => '    <u>Полка ' + esc(s) + ':</u>' + NL + '        ' + byShelf[s].join(',' + NL + '        '));
  return [''].concat(blocks).join(NL);
}

const fallbackChat = (() => { try { return $('Выделяю переменные пользователя').first().json.chat_id; } catch (e) { return null; } })();
const NL = String.fromCharCode(10);
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const ok = r.status === 'ok' && r.report_id;
  if (ok) {
    const head = (r.route_code ? '<b>Маршрут: ' + esc(r.route_code) + '</b>' + NL : '')
      + 'Магазин: ' + esc(r.store_name || '—');
    const text = head + NL + readout(r)
      + NL + NL + 'Всё верно?' + NL + 'Нажмите кнопку утвердить, если данные корректны.'
      + NL + 'И кнопку переснять в случае ошибок.';
    const reply_markup = JSON.stringify({ inline_keyboard: [[
      { text: '✅ Утвердить', callback_data: 'approve:' + r.report_id },
      { text: '🔄 Переснять',  callback_data: 'reject:'  + r.report_id },
    ]] });
    out.push({ json: { kind: 'ok', chat_id: r.chat_id || fallbackChat, report_id: r.report_id, text, reply_markup } });
  } else {
    out.push({ json: { kind: 'err', chat_id: r.chat_id || fallbackChat, text: '❌ Фото не обработалось. Пришлите его ещё раз.' } });
  }
}
return out;

// Кэш листа Admins в staticData — минус один поход в Google Sheets на каждое действие.
const TTL_MS = 60 * 1000;
const st = $getWorkflowStaticData('global');
const fresh = !!(Array.isArray(st.adminsRows) && st.adminsRows.length
                 && st.adminsAt && (Date.now() - st.adminsAt) < TTL_MS);
return [{ json: { fresh, __rows: fresh ? st.adminsRows : [] } }];

// Свежие строки из Sheets кладём в кэш и передаём дальше как есть.
const rows = $input.all().map(i => i.json);
const st = $getWorkflowStaticData('global');
st.adminsRows = rows;
st.adminsAt = Date.now();
return rows.length ? rows.map(json => ({ json })) : [{ json: { __rows: [] } }];

// Первый показ кнопок: маршрут агента, сегодняшний день, страница 1.
const DAYS = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
const today = DAYS[new Date(Date.now() + 5*3600*1000).getUTCDay()];  // tzdata нет — фикс. UTC+5
const a = $('Проверка совпадения с базой').first().json;
return [{ json: {
  route_code: String(a.route_code || ''),
  day: today,
  mode: 'd',
  page: 1,
  answer_text: '',
} }];

// Пагинация и переключение «сегодня ↔ все точки». Маршрут едет в callback_data,
// поэтому быстрая ветка обходится без чтения Admins.
const DAYS = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
const today = DAYS[new Date(Date.now() + 5*3600*1000).getUTCDay()];  // tzdata нет — фикс. UTC+5
const cb = $('Входящее сообщение').first().json.callback_query;
const data = String(cb.data || '');

let page = 1, route = '', mode = 'd';
if (data.startsWith('page:')) {
  const p = data.slice(5).split('|');      // n | route_code | mode
  page = parseInt(p[0], 10) || 1;
  route = String(p[1] || '');
  mode = (p[2] === 'a') ? 'a' : 'd';
} else if (data.startsWith('all|')) {
  route = String(data.slice(4) || '');
  mode = 'a';
}

return [{ json: {
  route_code: route,
  day: today,
  mode,
  page,
  answer_text: '',
  chat_id: cb.message.chat.id,
  message_id: cb.message.message_id,
} }];

// Агент нажал кнопку из устаревшей клавиатуры — перерисовываем список заново.
const DAYS = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
const today = DAYS[new Date(Date.now() + 5*3600*1000).getUTCDay()];  // tzdata нет — фикс. UTC+5
const a = $('Проверка совпадения с базой').first().json;
const cb = $('Входящее сообщение').first().json.callback_query;
return [{ json: {
  route_code: String(a.route_code || ''),
  day: today,
  mode: 'd',
  page: 1,
  answer_text: 'Список точек обновился — выберите ещё раз',
  chat_id: cb.message.chat.id,
  message_id: cb.message.message_id,
} }];

// Строки альбома, которые захватил ИМЕННО этот прогон. Пусто → молча выходим.
const rows = $input.all().map(i => i.json).filter(r => r && r.row_key);
if (!rows.length) return [];
rows.sort((a, b) => (Number(a.message_id) || 0) - (Number(b.message_id) || 0));
return [{ json: { count: rows.length, rows } }];
